# Good - utf8 mode rejects invalid bytes
# The default utf8-lossy mode replaces invalid bytes

# So when we have 0x80, 0x81, 0x82, 0x83:
# utf8-lossy would replace each with U+FFFD?
# OR it replaces maximal invalid sequences?

# In Rust's from_utf8_lossy:
# 0x80 is invalid, next char 0x81 could be:
#   If 0x80 started a 2-byte sequence (110xxxxx), 0x81 = 10000001 could be continuation
#   Actually 0x80 = 10000000 which is ALREADY a continuation byte, not a start byte
#   So 0x80 alone = 1 replacement char
#   0x81 alone = 1 replacement char
#   etc.

# Let me test Rust behavior:
cat > /tmp/test_utf8.rs << 'EOF'
fn main() {
    let bytes = vec![0x80u8, 0x81, 0x82, 0x83];
    let s = String::from_utf8_lossy(&bytes);
    println!("Result: {:?}", s);
    println!("Chars: {}", s.chars().count());
    for c in s.chars() {
        println!("  {:?} = U+{:04X}", c, c as u32);
    }
}
EOF
rustc /tmp/test_utf8.rs -o /tmp/test_utf8 && /tmp/test_utf8

