# Each of these gives 1 column! So EVERY valid unicode char = 1 column!
# Then 4 invalid bytes (-> 4 U+FFFDs) should be 4 cols = 2 cells.
# But we got 5 cells = 10 cols??
# 
# Unless... invalid bytes in utf8-lossy mode are NOT being replaced character-by-character?

# Let me check what Rust's from_utf8_lossy actually does with bytes like these:
cat > /tmp/test_utf8_2.rs << 'EOF'
fn main() {
    // Test bytes: 0x80, 0x81, 0x82, 0x83
    let bytes = vec![0x80u8, 0x81, 0x82, 0x83];
    let s = String::from_utf8_lossy(&bytes);
    println!("from_utf8_lossy of 80 81 82 83: {:?} len={}", s, s.len());
    println!("chars: {}", s.chars().count());
    for c in s.chars() {
        let b = c.to_string().into_bytes();
        println!("  {:?} = U+{:04X} bytes={:?}", c, c as u32, b);
    }

    // Also test known valid UTF-8 sequences with invalid continuation
    let bytes2 = vec![0xc3u8, 0x80];  // Start of 2-byte seq, invalid continuation (0x80 is valid continuation actually)
    let bytes3 = vec![0xc3u8, 0x20];  // Start of 2-byte seq, invalid continuation

    let s2 = String::from_utf8_lossy(&bytes2);
    let s3 = String::from_utf8_lossy(&bytes3);
    println!("\n0xC3 0x80: {:?} len={} chars={}", s2, s2.len(), s2.chars().count());
    println!("0xC3 0x20: {:?} len={} chars={}", s3, s3.len(), s3.chars().count());
}
EOF
