        return;
    }

    let output_rows = process_minimap(&lines, cli.horizontal_scale, cli.vertical_scale, &cli.encoding);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for cells in &output_rows {
        // Output braille chars
        let mut row_len = 0;
        for &bits in cells {
            let ch = encode_braille_cell(bits);
            // Write UTF-8 encoded braille char
            let mut buf = [0u8; 4];
