fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse arguments manually
    let mut file: Option<String> = None;
    let mut h_scale: f64 = 1.0;
    let mut v_scale: f64 = 1.0;
    let mut padding: Option<usize> = None;
    let mut lossy = true;
    let mut i = 1;
    let mut completion_shell: Option<String> = None;

    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                // Check if it's for a subcommand
                print_usage();
                return;
            }
            "--version" => {
                println!("code-minimap 0.6.8");
                return;
            }
            "-H" | "--horizontal-scale" => {
                i += 1;
                if i < args.len() {
                    h_scale = args[i].parse().unwrap_or(1.0);
                }
            }
            "-V" | "--vertical-scale" => {
                i += 1;
                if i < args.len() {
                    v_scale = args[i].parse().unwrap_or(1.0);
                }
            }
            "--padding" => {
                i += 1;
                if i < args.len() {
                    padding = args[i].parse().ok();
                }
            }
            "--encoding" => {
                i += 1;
                if i < args.len() {
                    lossy = args[i] != "utf8";
                }
            }
            "completion" => {
                i += 1;
                if i < args.len() {
                    if args[i] == "--help" || args[i] == "-h" {
                        eprintln!("Generate shell completion file");
                        eprintln!("");
                        eprintln!("Usage: code-minimap completion <SHELL>");
                        eprintln!("");
                        eprintln!("Arguments:");
                        eprintln!("  <SHELL>");
                        eprintln!("          Target shell name [possible values: bash, elvish, fish, powershell, zsh]");
                        eprintln!("");
                        eprintln!("Options:");
                        eprintln!("  -h, --help");
                        eprintln!("          Print help");
                        return;
                    }
                    completion_shell = Some(args[i].clone());
                }
                break;
            }
            "help" => {
                print_usage();
                return;
            }
            s if s.starts_with('-') => {
                // Unknown option, skip
            }
            s => {
                if file.is_none() {
                    file = Some(s.to_string());
                }
            }
        }
        i += 1;
    }

    // Handle completion
    if let Some(shell) = completion_shell {
        generate_completion(&shell);
        return;
    }

    // Read input
    let input_bytes: Vec<u8> = if let Some(ref file_path) = file {
        match File::open(file_path) {
            Ok(mut f) => {
                let mut buf = Vec::new();
                if let Err(e) = f.read_to_end(&mut buf) {
                    eprintln!("code-minimap: {}", e);
                    std::process::exit(1);
                }
                buf
            }
            Err(e) => {
                eprintln!("code-minimap: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        if let Err(e) = io::stdin().read_to_end(&mut buf) {
            eprintln!("code-minimap: {}", e);
            std::process::exit(1);
        }
        buf
    };

    // Validate UTF-8 if strict encoding
    if !lossy {
        if std::str::from_utf8(&input_bytes).is_err() {
            eprintln!("code-minimap: stream did not contain valid UTF-8");
            std::process::exit(1);
        }
    }

    // Split into lines (by \n)
    let lines: Vec<Vec<u8>> = {
        let mut result = Vec::new();
        let mut current = Vec::new();
        for &b in &input_bytes {
            if b == b'\n' {
                result.push(current.clone());
                current.clear();
            } else {
                current.push(b);
            }
        }
        if !current.is_empty() {
            result.push(current);
        }
        result
    };

    if lines.is_empty() {
        return;
    }

    let output_rows = generate_minimap(&lines, h_scale, v_scale, lossy);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut row_buf = Vec::with_capacity(256);

    for cells in &output_rows {
        row_buf.clear();
        let mut row_char_len = 0;

        for &bits in cells {
            encode_braille_char(bits, &mut row_buf);
            row_char_len += 1;
        }

        // Apply padding
        if let Some(pad) = padding {
            while row_char_len < pad {
                row_buf.push(b' ');
                row_char_len += 1;
            }
        }

        row_buf.push(b'\n');
        out.write_all(&row_buf).unwrap();
    }
}

fn generate_completion(shell: &str) {
    match shell {
        "bash" => print_bash_completion(),
        "zsh" => print_zsh_completion(),
        "fish" => print_fish_completion(),
        "elvish" => print_elvish_completion(),
        "powershell" => print_powershell_completion(),
        _ => {
            eprintln!("Unknown shell: {}", shell);
            std::process::exit(1);
        }
    }
}

