use std::fs::File;
use std::io::{self, Read, Write};

fn is_visible_char(c: char) -> bool {
    !c.is_whitespace()
}

struct LineInfo {
    out_start: usize,   // scaled start column (from first visible char)
    out_end: i64,       // scaled end column (from last visible char); -1 if empty
    has_content: bool,  // true if there were visible chars
    has_bar: bool,      // true if bar should be drawn (out_start <= out_end)
}

fn compute_line_info(line_bytes: &[u8], h_scale: f64, lossy: bool) -> LineInfo {
    // Decode the line
    let line_str: String = if lossy {
        String::from_utf8_lossy(line_bytes).into_owned()
    } else {
        String::from_utf8(line_bytes.to_vec()).unwrap_or_default()
    };

    // Find first and last non-whitespace char's byte offset
    let mut start_byte: i64 = -1;
    let mut end_byte: i64 = -1;
    let mut byte_offset: usize = 0;

    for c in line_str.chars() {
        let char_len = c.len_utf8();
        if is_visible_char(c) {
            if start_byte < 0 {
                start_byte = byte_offset as i64;
            }
            end_byte = byte_offset as i64;
        }
        byte_offset += char_len;
    }

    let has_content = start_byte >= 0;

    if has_content {
        // Compute scaled output columns
        let out_start = (start_byte as f64 * h_scale).floor() as i64;
        let out_end = ((end_byte as f64 + 1.0) * h_scale).floor() as i64 - 1;

        // out_end might be negative if h_scale is very small
        // The LINE STILL EXISTS but might have no output cells
        let has_bar = out_end >= 0 && out_start <= out_end;

        LineInfo {
            out_start: out_start.max(0) as usize,
            out_end,
            has_content: true,
            has_bar,
        }
    } else {
        // Blank/empty line: treat as 1 phantom byte at position 0
        // out_start = 0, out_end = floor(1 * H) - 1
        let out_end = h_scale.floor() as i64 - 1;

        LineInfo {
            out_start: 0,
            out_end,
            has_content: false,
            has_bar: false, // blank lines never draw a bar
        }
    }
}

// Braille bit layout for minimap:
// row_pos 0: left=bit0, right=bit3
// row_pos 1: left=bit1, right=bit4
// row_pos 2: left=bit2, right=bit5
// row_pos 3: left=bit6, right=bit7
const ROW_BITS_LEFT: [u8; 4] = [0, 1, 2, 6];
const ROW_BITS_RIGHT: [u8; 4] = [3, 4, 5, 7];

fn generate_minimap(
    lines: &[Vec<u8>],
    h_scale: f64,
    v_scale: f64,
    lossy: bool,
) -> Vec<Vec<u8>> {
    let n_lines = lines.len();
    if n_lines == 0 {
        return vec![];
    }

    // Compute info for each line
    let line_infos: Vec<LineInfo> = lines.iter()
        .map(|lb| compute_line_info(lb, h_scale, lossy))
        .collect();

    // Vertical scale: effective V <= 1.0
    let v_eff = v_scale.min(1.0_f64);

    // Number of output rows
    let max_row_pos = ((n_lines - 1) as f64 * v_eff).floor() as usize;
    let n_output_rows = max_row_pos / 4 + 1;

    let mut output: Vec<Vec<u8>> = Vec::with_capacity(n_output_rows);

    for output_row_idx in 0..n_output_rows {
        let base_row_pos = output_row_idx * 4;

        // Find the max output column for this row (determines row width)
        let mut max_out_col: i64 = -1;

        for (line_idx, info) in line_infos.iter().enumerate() {
            let row_pos = (line_idx as f64 * v_eff).floor() as usize;
            if row_pos / 4 == output_row_idx {
                if info.out_end > max_out_col {
                    max_out_col = info.out_end;
                }
            }
        }

        if max_out_col < 0 {
            // No output for this row - just emit empty row (newline)
            output.push(vec![]);
            continue;
        }

        let n_cells = max_out_col as usize / 2 + 1;
        let mut cells = vec![0u8; n_cells];

        // Set bits for each line that contributes to this row
        for (line_idx, info) in line_infos.iter().enumerate() {
            if !info.has_bar {
                continue;
            }
            let row_pos = (line_idx as f64 * v_eff).floor() as usize;
            if row_pos / 4 != output_row_idx {
                continue;
            }

            let row_within = row_pos - base_row_pos; // 0-3
            let left_bit = ROW_BITS_LEFT[row_within];
            let right_bit = ROW_BITS_RIGHT[row_within];

            let bar_end = info.out_end as usize;

            for col in info.out_start..=bar_end {
                let cell_idx = col / 2;
                if cell_idx >= n_cells {
                    break;
                }
                let within_col = col % 2;
                let bit = if within_col == 0 { left_bit } else { right_bit };
                cells[cell_idx] |= 1u8 << bit;
            }
        }

        output.push(cells);
    }

    output
}

fn encode_braille_char(bits: u8, buf: &mut Vec<u8>) {
    let cp = 0x2800u32 + bits as u32;
    // UTF-8 encode the code point (all braille are in range 0x2800-0x28FF = 3-byte UTF-8)
    buf.push(0xE0 | ((cp >> 12) as u8));
    buf.push(0x80 | (((cp >> 6) & 0x3F) as u8));
    buf.push(0x80 | ((cp & 0x3F) as u8));
}

fn print_usage(prog_name: &str) {
    eprintln!("A high performance code minimap generator");
    eprintln!("");
    eprintln!("Usage: {} [OPTIONS] [FILE] [COMMAND]", prog_name);
    eprintln!("");
    eprintln!("Commands:");
    eprintln!("  completion");
    eprintln!("          Generate shell completion file");
    eprintln!("  help");
    eprintln!("          Print this message or the help of the given subcommand(s)");
    eprintln!("");
    eprintln!("Arguments:");
    eprintln!("  [FILE]");
    eprintln!("          File to read");
    eprintln!("");
    eprintln!("Options:");
    eprintln!("  -H, --horizontal-scale <HSCALE>");
    eprintln!("          Specify horizontal scale factor [default: 1.0]");
    eprintln!("  -V, --vertical-scale <VSCALE>");
    eprintln!("          Specify vertical scale factor [default: 1.0]");
    eprintln!("      --padding <PADDING>");
    eprintln!("          Specify padding width");
    eprintln!("      --encoding <ENCODING>");
    eprintln!("          Specify input encoding [default: utf8-lossy] [possible values: utf8-lossy, utf8]");
    eprintln!("      --version");
    eprintln!("          Print version");
    eprintln!("  -h, --help");
    eprintln!("          Print help");
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let prog_name = args.get(0)
        .and_then(|p| std::path::Path::new(p).file_name())
        .and_then(|n| n.to_str())
        .unwrap_or("code-minimap")
        .to_string();

    // Parse arguments manually
    let mut file: Option<String> = None;
    let mut h_scale: f64 = 1.0;
    let mut v_scale: f64 = 1.0;
    let mut padding: Option<usize> = None;
    let mut lossy = true;
    let mut i = 1;
    let mut completion_shell: Option<String> = None;

    while i < args.len() {
        let arg = args[i].as_str();
        match arg {
            "-h" | "--help" => {
                print_usage(&prog_name);
                return;
            }
            "--version" => {
                println!("code-minimap 0.6.8");
                return;
            }
            "-H" | "--horizontal-scale" => {
                i += 1;
                if i < args.len() {
                    h_scale = args[i].parse().unwrap_or(1.0);
                }
            }
            "-V" | "--vertical-scale" => {
                i += 1;
                if i < args.len() {
                    v_scale = args[i].parse().unwrap_or(1.0);
                }
            }
            "--padding" => {
                i += 1;
                if i < args.len() {
                    padding = args[i].parse().ok();
                }
            }
            "--encoding" => {
                i += 1;
                if i < args.len() {
                    lossy = args[i] != "utf8";
                }
            }
            "completion" => {
                i += 1;
                if i < args.len() {
                    if args[i] == "--help" || args[i] == "-h" {
                        eprintln!("Generate shell completion file");
                        eprintln!("");
                        eprintln!("Usage: {} completion <SHELL>", prog_name);
                        eprintln!("");
                        eprintln!("Arguments:");
                        eprintln!("  <SHELL>");
                        eprintln!("          Target shell name [possible values: bash, elvish, fish, powershell, zsh]");
                        eprintln!("");
                        eprintln!("Options:");
                        eprintln!("  -h, --help");
                        eprintln!("          Print help");
                        return;
                    }
                    completion_shell = Some(args[i].clone());
                }
                i += 1;
                continue;
            }
            "help" => {
                // Check if it's help for a subcommand
                if i + 1 < args.len() {
                    match args[i + 1].as_str() {
                        "completion" => {
                            eprintln!("Generate shell completion file");
                            eprintln!("");
                            eprintln!("Usage: {} completion <SHELL>", prog_name);
                            eprintln!("");
                            eprintln!("Arguments:");
                            eprintln!("  <SHELL>");
                            eprintln!("          Target shell name [possible values: bash, elvish, fish, powershell, zsh]");
                            eprintln!("");
                            eprintln!("Options:");
                            eprintln!("  -h, --help");
                            eprintln!("          Print help");
                        }
                        _ => print_usage(&prog_name),
                    }
                } else {
                    print_usage(&prog_name);
                }
                return;
            }
            s if s.starts_with("--horizontal-scale=") => {
                let val = &s["--horizontal-scale=".len()..];
                h_scale = val.parse().unwrap_or(1.0);
            }
            s if s.starts_with("--vertical-scale=") => {
                let val = &s["--vertical-scale=".len()..];
                v_scale = val.parse().unwrap_or(1.0);
            }
            s if s.starts_with("--padding=") => {
                let val = &s["--padding=".len()..];
                padding = val.parse().ok();
            }
            s if s.starts_with("--encoding=") => {
                let val = &s["--encoding=".len()..];
                lossy = val != "utf8";
            }
            s if s.starts_with('-') => {
                // Unknown option - ignore for now
            }
            s => {
                if file.is_none() {
                    file = Some(s.to_string());
                }
            }
        }
        i += 1;
    }

    // Handle completion
    if let Some(shell) = completion_shell {
        generate_completion(&shell, &prog_name);
        return;
    }

    // Read input
    let input_bytes: Vec<u8> = if let Some(ref file_path) = file {
        match File::open(file_path) {
            Ok(mut f) => {
                let mut buf = Vec::new();
                if let Err(e) = f.read_to_end(&mut buf) {
                    eprintln!("code-minimap: {}", e);
                    std::process::exit(1);
                }
                buf
            }
            Err(e) => {
                eprintln!("code-minimap: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        if let Err(e) = io::stdin().read_to_end(&mut buf) {
            eprintln!("code-minimap: {}", e);
            std::process::exit(1);
        }
        buf
    };

    // Validate UTF-8 if strict encoding
    if !lossy {
        if std::str::from_utf8(&input_bytes).is_err() {
            eprintln!("code-minimap: stream did not contain valid UTF-8");
            std::process::exit(1);
        }
    }

    // Split into lines (by \n)
    let lines: Vec<Vec<u8>> = {
        let mut result = Vec::new();
        let mut current = Vec::new();
        for &b in &input_bytes {
            if b == b'\n' {
                result.push(current.clone());
                current.clear();
            } else {
                current.push(b);
            }
        }
        if !current.is_empty() {
            result.push(current);
        }
        result
    };

    if lines.is_empty() {
        return;
    }

    let output_rows = generate_minimap(&lines, h_scale, v_scale, lossy);

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut row_buf = Vec::with_capacity(256);

    for cells in &output_rows {
        row_buf.clear();
        let mut row_char_len = 0;

        for &bits in cells {
            encode_braille_char(bits, &mut row_buf);
            row_char_len += 1;
        }

        // Apply padding
        if let Some(pad) = padding {
            while row_char_len < pad {
                row_buf.push(b' ');
                row_char_len += 1;
            }
        }

        row_buf.push(b'\n');
        out.write_all(&row_buf).unwrap();
    }
}

fn generate_completion(shell: &str, prog_name: &str) {
    match shell {
        "bash" => print_bash_completion(prog_name),
        "zsh" => print_zsh_completion(prog_name),
        "fish" => print_fish_completion(prog_name),
        "elvish" => print_elvish_completion(prog_name),
        "powershell" => print_powershell_completion(prog_name),
        _ => {
            eprintln!("error: invalid value '{}' for '<SHELL>'", shell);
            std::process::exit(1);
        }
    }
}

fn print_bash_completion(prog_name: &str) {
    let name = prog_name.replace('-', "__").replace(' ', "_");
    println!(r#"_{name}() {{
    local i cur prev opts cmd
    COMPREPLY=()
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    prev="${{COMP_WORDS[COMP_CWORD-1]}}"
    cmd=""
    opts=""

    for i in ${{COMP_WORDS[@]}}
    do
        case "${{cmd}},${{i}}" in
            ",$1")
                cmd="{name}"
                ;;
            {name},completion)
                cmd="{name}__completion"
                ;;
            {name},help)
                cmd="{name}__help"
                ;;
            *)
                ;;
        esac
    done

    case "${{cmd}}" in
        {name})
            opts="-H -V -h --horizontal-scale --vertical-scale --padding --encoding --version --help completion help [FILE]"
            if [[ ${{cur}} == --* || ${{cur}} == -* ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            case "${{prev}}" in
                --encoding)
                    COMPREPLY=($(compgen -W "utf8-lossy utf8" -- "${{cur}}"))
                    return 0
                    ;;
                *)
                    COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                    return 0
                    ;;
            esac
            ;;
        {name}__completion)
            opts="-h --help bash elvish fish powershell zsh"
            if [[ ${{cur}} == --* || ${{cur}} == -* ]] ; then
                COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
        {name}__help)
            opts="completion help"
            COMPREPLY=( $(compgen -W "${{opts}}" -- "${{cur}}") )
            return 0
            ;;
    esac
}}

if [[ "${{BASH_VERSINFO[0]}}" -eq 4 && "${{BASH_VERSINFO[1]}}" -ge 4 || "${{BASH_VERSINFO[0]}}" -gt 4 ]]; then
    complete -F _{name} -o nosort -o bashdefault -o default {prog_name}
else
    complete -F _{name} -o bashdefault -o default {prog_name}
fi
"#, name=name, prog_name=prog_name);
}

