_arguments "${{_arguments_options[@]}}" \
&& ret=0
;;
(help)
_arguments "${{_arguments_options[@]}}" \
&& ret=0
;;
        esac
    ;;
esac
;;
        esac
    ;;
esac
}}

(( $+functions[_{fn_name}_commands] )) ||
