            break
        }}
        '{prog_name};completion' {{
            [CompletionResult]::new('-h', 'h', [CompletionResultType]::ParameterName, 'Print help')
            [CompletionResult]::new('--help', 'help', [CompletionResultType]::ParameterName, 'Print help')
            [CompletionResult]::new('bash', 'bash', [CompletionResultType]::ParameterValue, '')
            [CompletionResult]::new('elvish', 'elvish', [CompletionResultType]::ParameterValue, '')
            [CompletionResult]::new('fish', 'fish', [CompletionResultType]::ParameterValue, '')
            [CompletionResult]::new('powershell', 'powershell', [CompletionResultType]::ParameterValue, '')
            [CompletionResult]::new('zsh', 'zsh', [CompletionResultType]::ParameterValue, '')
            break
        }}
