                    if args[i] == "--help" || args[i] == "-h" {
                        eprintln!("Generate shell completion file");
                        eprintln!("");
                        eprintln!("Usage: {} completion <SHELL>", prog_name);
                        eprintln!("");
                        eprintln!("Arguments:");
