use std::fs::File;
use std::io::{self, Read, Write};

// Embedded completion scripts
const COMPLETION_BASH: &str = include_str!("../completions/bash.txt");
const COMPLETION_ZSH: &str = include_str!("../completions/zsh.txt");
const COMPLETION_FISH: &str = include_str!("../completions/fish.txt");
const COMPLETION_ELVISH: &str = include_str!("../completions/elvish.txt");
const COMPLETION_POWERSHELL: &str = include_str!("../completions/powershell.txt");

fn is_visible_char(c: char) -> bool {
    !c.is_whitespace()
}

struct LineInfo {
    out_start: usize,   // scaled start column (from first visible char)
    out_end: i64,       // scaled end column (from last visible char); -1 if empty
    has_bar: bool,      // true if bar should be drawn (out_start <= out_end and has_content)
}

fn compute_line_info(line_bytes: &[u8], h_scale: f64, lossy: bool) -> LineInfo {
    // Decode the line
    let line_str: String = if lossy {
        String::from_utf8_lossy(line_bytes).into_owned()
    } else {
        String::from_utf8(line_bytes.to_vec()).unwrap_or_default()
    };

    // Find first and last non-whitespace char's byte offset
    let mut start_byte: i64 = -1;
    let mut end_byte: i64 = -1;
    let mut byte_offset: usize = 0;

    for c in line_str.chars() {
        let char_len = c.len_utf8();
        if is_visible_char(c) {
            if start_byte < 0 {
                start_byte = byte_offset as i64;
            }
            end_byte = byte_offset as i64;
        }
        byte_offset += char_len;
    }

    let has_content = start_byte >= 0;

    if has_content {
        // Compute scaled output columns
        let out_start = (start_byte as f64 * h_scale).floor() as i64;
        let out_end = ((end_byte as f64 + 1.0) * h_scale).floor() as i64 - 1;

        // has_bar: bar is drawn if out_start <= out_end (both non-negative)
        let has_bar = out_end >= 0 && out_start <= out_end;

        LineInfo {
            out_start: out_start.max(0) as usize,
            out_end,
            has_bar,
        }
    } else {
        // Blank/empty line: treat as 1 phantom byte at position 0
        // out_start = 0, out_end = floor(1 * H) - 1
        let out_end = h_scale.floor() as i64 - 1;

        LineInfo {
            out_start: 0,
            out_end,
            has_bar: false, // blank lines never draw a bar
        }
    }
}

// Braille bit layout for minimap:
// row_pos 0: left=bit0, right=bit3
// row_pos 1: left=bit1, right=bit4
// row_pos 2: left=bit2, right=bit5
// row_pos 3: left=bit6, right=bit7
const ROW_BITS_LEFT: [u8; 4] = [0, 1, 2, 6];
const ROW_BITS_RIGHT: [u8; 4] = [3, 4, 5, 7];

fn generate_minimap(
    lines: &[Vec<u8>],
    h_scale: f64,
    v_scale: f64,
    lossy: bool,
) -> Vec<Vec<u8>> {
    let n_lines = lines.len();
    if n_lines == 0 {
        return vec![];
    }

    // Compute info for each line
    let line_infos: Vec<LineInfo> = lines.iter()
        .map(|lb| compute_line_info(lb, h_scale, lossy))
        .collect();

    // Vertical scale: effective V <= 1.0 (V > 1.0 doesn't increase detail)
    let v_eff = v_scale.min(1.0_f64);

    // Number of output rows
    let max_row_pos = ((n_lines - 1) as f64 * v_eff).floor() as usize;
    let n_output_rows = max_row_pos / 4 + 1;

    let mut output: Vec<Vec<u8>> = Vec::with_capacity(n_output_rows);

    for output_row_idx in 0..n_output_rows {
        let base_row_pos = output_row_idx * 4;

        // Find the max output column for this row (determines row width)
        let mut max_out_col: i64 = -1;

        for (line_idx, info) in line_infos.iter().enumerate() {
            let row_pos = (line_idx as f64 * v_eff).floor() as usize;
            if row_pos / 4 == output_row_idx {
                if info.out_end > max_out_col {
                    max_out_col = info.out_end;
                }
            }
        }

        if max_out_col < 0 {
            // No output for this row - just emit empty row (newline)
            output.push(vec![]);
            continue;
        }

        let n_cells = max_out_col as usize / 2 + 1;
        let mut cells = vec![0u8; n_cells];

        // Set bits for each line that contributes to this row
        for (line_idx, info) in line_infos.iter().enumerate() {
            if !info.has_bar {
                continue;
            }
            let row_pos = (line_idx as f64 * v_eff).floor() as usize;
            if row_pos / 4 != output_row_idx {
                continue;
            }

            let row_within = row_pos - base_row_pos; // 0-3
            let left_bit = ROW_BITS_LEFT[row_within];
            let right_bit = ROW_BITS_RIGHT[row_within];

            let bar_end = info.out_end as usize;

            for col in info.out_start..=bar_end {
                let cell_idx = col / 2;
                if cell_idx >= n_cells {
                    break;
                }
                let within_col = col % 2;
                let bit = if within_col == 0 { left_bit } else { right_bit };
                cells[cell_idx] |= 1u8 << bit;
            }
        }

        output.push(cells);
    }

    output
}

fn encode_braille_char(bits: u8, buf: &mut Vec<u8>) {
    let cp = 0x2800u32 + bits as u32;
    // UTF-8 encode the code point (all braille are in range 0x2800-0x28FF = 3-byte UTF-8)
    buf.push(0xE0 | ((cp >> 12) as u8));
    buf.push(0x80 | (((cp >> 6) & 0x3F) as u8));
    buf.push(0x80 | ((cp & 0x3F) as u8));
}

